parameters.jsCode:
const c = $('Assemble Draft Input').first().json;
let raw = $input.first().json;
if (raw && raw.output) raw = raw.output;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = null; } }
function fail(reason) { return [{ json: { ...c, draft_valid: false, failure_reason: reason } }]; }
if (!raw || typeof raw !== 'object') return fail('The drafting model returned no parsable JSON.');
if (typeof raw.content !== 'string' || raw.content.trim().length < 40)
  return fail('The drafting model returned no usable content.');

const content = raw.content;
const missingMarkers = (content.match(/\[MISSING:[^\]]*\]/g) || []);
const unverified = (content.match(/\[UNVERIFIED\]/g) || []);
const issues = Array.isArray(raw.unresolved_issues) ? raw.unresolved_issues.map(String) : [];

let review = 'PASSED';
if (missingMarkers.length) review = 'NEEDS_INFORMATION';
if (issues.length || c.research_status === 'UNVERIFIED') review = 'NEEDS_HUMAN_REVIEW';
if (['NEEDS_INFORMATION','NEEDS_HUMAN_REVIEW'].includes(String(raw.review_status))) review = String(raw.review_status);
if (missingMarkers.length && review === 'PASSED') review = 'NEEDS_INFORMATION';

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0; }
  return ('00000000' + h.toString(16)).slice(-8);
}
const contentHash = fnv1a(content) + fnv1a(content.split('').reverse().join(''))
  + ('0000' + (content.length % 65536).toString(16)).slice(-4);

const draftId = 'DRF-' + c.action_id.replace('ACT-', '') + '-v' + c.next_version;
const approvalId = 'APR-' + fnv1a(c.action_id + '|' + contentHash + '|' + c.next_version).toUpperCase()
  + fnv1a(c.matter_id).toUpperCase();
const recipient = String(c.recipient || raw.recommended_recipient || '').trim();
const needsApproval = c.requires_approval || String(c.channel).toUpperCase() === 'GMAIL';

// Delivery mode is refined from the draft type the model actually produced.
const dtype = String(raw.draft_type || 'DOCUMENT').toUpperCase().replace(/[^A-Z_]/g, '_');
let delivery = c.delivery_mode;
if ((c.doc_types || []).some(t => dtype.includes(t))) delivery = 'PDF_ATTACHMENT';

const deliveryText = {
  EMAIL_BODY: 'the text below, sent as the body of an email',
  PDF_ATTACHMENT: 'a PDF generated from this draft and attached to an email',
  DOCX_ATTACHMENT: 'a Word file generated from this draft and attached to an email',
  DRIVE_LINK: 'a Google Drive document shared with the recipient, with the link emailed',
}[delivery] || 'an email';

return [{ json: { ...c,
  draft_valid: true, failure_reason: '',
  draft_id: draftId, version: c.next_version,
  draft_type: dtype,
  subject: String(raw.subject || (c.matter_title + ' [' + c.matter_id + '][' + c.action_id + ']')).slice(0, 200),
  content,
  cover_note: String(raw.cover_note || '').slice(0, 3000),
  changes_summary: String(raw.changes_summary || (c.next_version === 1 ? 'First version.' : '')),
  source_refs_json: JSON.stringify(Array.isArray(raw.source_refs) ? raw.source_refs : []),
  evidence_refs_json: JSON.stringify(Array.isArray(raw.evidence_refs) ? raw.evidence_refs : []),
  unresolved_issues: issues,
  missing_marker_count: missingMarkers.length,
  unverified_marker_count: unverified.length,
  review_status: review, content_hash: contentHash, approval_id: approvalId,
  recipient, recipient_known: !!recipient, needs_approval: needsApproval,
  delivery_mode: delivery, delivery_text: deliveryText,
  owner_summary: String(raw.owner_summary || '').slice(0, 800),
  approve_cb: 'A|' + approvalId + '|APPROVE',
  approve_link_cb: 'A|' + approvalId + '|APPROVE_LINK',
  reject_cb: 'A|' + approvalId + '|REJECT',
  edit_cb: 'A|' + approvalId + '|REQUEST_EDIT' } }];

