parameters.jsCode:
// Chooses which action to draft, correcting four faults in Build Draft Context's pick:
// it excluded only COMPLETED/SENT/FAILED so a drafted action was re-picked forever; it
// read readiness from a status column nothing maintains; it ignored plan stamps so a
// dependency could resolve against a superseded action; and it omitted PRESERVE_FOOTAGE,
// the most time-critical action in a hit and run.
//
// Draftability is deliberately separate from sendability. A preservation request can be
// drafted with the recipient unresolved -- the Approval Gate still refuses to send
// without a valid address -- so an unknown email must not block writing the letter.
const ctx = $input.first().json;
const cfg = $('Config').first().json;
const wanted = String(cfg.matter_ref || cfg.session_matter_id || '').toUpperCase();

const matters = $('Load Matters').all().map(i => i.json).filter(r => r && r.matter_id);
const rawActions = $('Load Actions').all().map(i => i.json).filter(r => r && r.action_id);
const drafts = $('Load Drafts').all().map(i => i.json).filter(r => r && r.draft_id);

function planRank(actionId) {
  const m = String(actionId).match(/-P([0-9A-Z]+)-\d{3}$/);
  if (!m) return -1;                       // legacy unstamped id: older than any plan
  const n = parseInt(m[1], 36);
  return Number.isNaN(n) ? -1 : n;
}
function currentPlanOnly(rows) {
  let best = -Infinity;
  for (const r of rows) { const k = planRank(r.action_id); if (k > best) best = k; }
  return { rows: rows.filter(r => planRank(r.action_id) === best), rank: best };
}

const DRAFTY = ['DRAFT_DOCUMENT','SEND_DOCUMENT','SEND_DEMAND','CONTACT_INSURER',
                'PRESERVE_FOOTAGE','FOLLOW_UP','REVIEW_DOCUMENT'];
const OUTBOUND = ['SEND_DOCUMENT','SEND_DEMAND','CONTACT_INSURER','PRESERVE_FOOTAGE','FOLLOW_UP'];
// Allowlist, not denylist, so an unrecognised status can never silently become draftable.
const CANDIDATE_STATUS = ['READY','BLOCKED'];
const DEP_SATISFIED = ['COMPLETED','SENT'];
const EMAIL = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

// A fatal context carries ONLY {fatal, reason}: no facts, no evidence, no sources.
// Re-picking here would draft a legal document from an empty context, which is exactly
// what this refusal path exists to prevent.
if (ctx.fatal) {
  const mm = matters.filter(m => String(m.matter_id).toUpperCase() === wanted);
  const m = mm.length ? mm[mm.length - 1] : null;
  const mineAll = rawActions.filter(a => String(a.matter_id).toUpperCase() === wanted);
  if (m && String(m.status).toUpperCase() === 'NEEDS_INFORMATION' && !mineAll.length) {
    let missing = [];
    try { missing = JSON.parse(m.missing_facts_json || '[]'); } catch (e) { missing = []; }
    const list = missing.slice(0, 12).map(x => '- ' + String(x).replace(/_/g, ' ')).join('\n');
    return [{ json: { fatal: true, reason:
      'Matter ' + m.matter_id + ' is still at NEEDS_INFORMATION. No plan and no actions exist yet.'
      + '\nI will not draft a legal document from facts I do not have.'
      + (missing.length ? ('\n\nStill missing (' + missing.length + '):\n' + list) : '')
      + '\n\nAnswer what you can in one message.\nSend /proceed ' + m.matter_id + '.' } }];
  }
  return [{ json: ctx }];
}

if (String(cfg.target_action_id || '').trim() || String(cfg.draft_ref || '').trim()) {
  return [{ json: { ...ctx, action_reselected: false } }];
}

const matterId = String(ctx.matter_id);
const forMatter = rawActions.filter(a => String(a.matter_id).toUpperCase() === matterId.toUpperCase());
const picked = currentPlanOnly(forMatter);
const mine = picked.rows;
const planLabel = picked.rank >= 0 ? ('plan P' + picked.rank.toString(36).toUpperCase()) : 'the original unstamped plan';

const byId = {};
for (const a of mine) byId[String(a.action_id)] = a;

function blockers(action, seen) {
  seen = seen || new Set();
  const id = String(action.action_id);
  if (seen.has(id)) return ['dependency cycle detected at ' + id];
  seen.add(id);
  let deps = [];
  try { deps = JSON.parse(action.depends_on_json || '[]'); } catch (e) { deps = []; }
  const out = [];
  for (const d of deps) {
    const dep = byId[String(d)];
    if (!dep) { out.push(String(d) + ' (not in ' + planLabel + ')'); continue; }
    if (DEP_SATISFIED.includes(String(dep.status).toUpperCase())) continue;
    const deeper = blockers(dep, seen);
    if (deeper.length) { for (const x of deeper) out.push(x); continue; }
    out.push(String(dep.action_id) + ' ' + String(dep.action_type) + ' (' + String(dep.status) + ')');
  }
  return out;
}

const docActions = mine.filter(a => DRAFTY.includes(String(a.action_type).toUpperCase()));
const candidates = docActions.filter(a => CANDIDATE_STATUS.includes(String(a.status).toUpperCase()));

const ready = [];
const waiting = [];
for (const a of candidates) {
  const b = blockers(a);
  if (b.length) waiting.push({ action: a, blockers: b });
  else ready.push(a);
}

// The owner needs to see where the work actually IS, not only why the next item is
// blocked. An action sitting at AWAITING_APPROVAL is the one thing they can act on, and
// omitting it made the refusal actively misleading.
function latestDraftFor(id) {
  const c = drafts.filter(d => String(d.action_id) === String(id))
    .sort((x, y) => Number(x.version || 0) - Number(y.version || 0));
  return c.length ? c[c.length - 1].draft_id : '';
}
function stateLines() {
  return docActions.map(a => {
    const st = String(a.status || '').toUpperCase();
    let note = '';
    if (st === 'AWAITING_APPROVAL') note = ' - waiting for YOUR approval';
    else if (st === 'HELD') note = ' - held after rejection';
    else if (st === 'DRAFTED' || st === 'NEEDS_REVIEW') note = ' - drafted, needs review';
    if (['AWAITING_APPROVAL','HELD','DRAFTED','NEEDS_REVIEW'].includes(st)) {
      const d = latestDraftFor(a.action_id);
      if (d) note += ', draft ' + d + ' (use /edit ' + d + ' to revise)';
    }
    return '- ' + a.action_id + ' ' + a.action_type + ' [' + st + ']' + note;
  });
}

if (!ready.length) {
  const head = waiting.length
    ? ('The next document on ' + matterId + ' is ' + waiting[0].action.action_id + ' '
       + waiting[0].action.action_type + '. Its earlier steps are not done.'
       + '\n\nWaiting on:\n' + waiting[0].blockers.map(x => '- ' + x).join('\n')
       + '\n\nI will not draft it out of order.')
    : ('I cannot start a new document on ' + matterId + ' right now.');
  return [{ json: { fatal: true, reason:
    head + '\n\nWhere every document on this matter stands:\n' + stateLines().join('\n')
    + '\n\nReasoning over ' + planLabel + ', ' + mine.length + ' action(s).' } }];
}

const a = ready[0];
const type = String(a.action_type || '').toUpperCase();
const rawRecipient = String(a.recipient || '').trim();
const isOutbound = OUTBOUND.includes(type);
const recipientOk = EMAIL.test(rawRecipient);
const needsRecipient = isOutbound && !recipientOk;

const chain = drafts.filter(d => String(d.action_id) === String(a.action_id))
  .sort((x, y) => Number(x.version || 0) - Number(y.version || 0));
const latest = chain.length ? chain[chain.length - 1] : null;

return [{ json: { ...ctx,
  action_id: a.action_id,
  action_type: type,
  action_description: String(a.description || ''),
  recipient: recipientOk ? rawRecipient : '',
  recipient_description: rawRecipient,
  needs_recipient: needsRecipient,
  channel: isOutbound ? 'GMAIL' : String(a.channel || 'NONE'),
  requires_approval: isOutbound ? true : String(a.requires_approval).toUpperCase() === 'TRUE',
  next_version: latest ? Number(latest.version || 0) + 1 : 1,
  prior_version: latest ? Number(latest.version || 0) : 0,
  prior_draft_id: latest ? latest.draft_id : '',
  prior_content: latest ? String(latest.content || '') : '',
  action_reselected: String(a.action_id) !== String(ctx.action_id),
  reselected_from: String(ctx.action_id || ''),
  plan_label: planLabel,
}}];

// F-04. What actually happened to the send?
//
// The three Gmail nodes and Share Document all run with onError: continueErrorOutput, and
// every one of those error outputs used to land on Mark Send Failed, which wrote the flat
// assertion "The send failed. Nothing was delivered." That claim is not knowable from an
// error alone. A socket timeout, a dropped connection or a 5xx can all occur AFTER Gmail has
// accepted the message, so the email may well be in the recipient's inbox.
//
// It was worse than a misleading sentence. Approval Gate check 7c deliberately ignores
// OUTBOUND_FAILED rows so that a genuine failure does not block a retry, and Mark Send Failed
// overwrites the OUTBOUND_PENDING row on the same delivery key. So an uncertain outcome
// erased the one record that was blocking a resend, and cleared the way to deliver the same
// legal communication twice.
//
// This node only ever claims "not sent" when the error proves the message never reached
// Gmail's queue: an authentication or permission refusal, a malformed request, a rejected
// recipient, or a quota refusal. Everything else, including anything unrecognised, is
// UNCERTAIN and must be resolved by a human. Fail closed means fail closed.
const it = $input.all()[0] || {};
const j = it.json || {};
const err = j.error || it.error || {};
const message = String(
  (err && (err.message || err.description)) || j.message ||
  (typeof j.error === 'string' ? j.error : '') || ''
).slice(0, 500);
const code = Number(
  (err && (err.httpCode || err.statusCode || err.code)) || j.httpCode || j.statusCode || 0
) || 0;
// If a provider message id came back, something was accepted. Log Outbound did not run, so
// this is still not a confirmed send, but it is certainly not "nothing was delivered".
const providerId = String(j.id || j.messageId || (j.result && j.result.id) || '');

const PROVES_NOT_SENT = /(invalid[_ ]?grant|unauthoriz|unauthentic|insufficient permission|forbidden|invalid to header|invalid recipient|recipient address required|malformed|invalid argument|precondition failed|quota exceeded|rate limit|daily limit exceeded|sending limit)/i;
const PROVES_UNKNOWN = /(etimedout|econnreset|enotfound|eai_again|econnrefused|epipe|socket hang up|timeout|timed out|aborted|network|gateway|unavailable|internal error)/i;

let outcome;
let why;
if (providerId) {
  outcome = 'UNCERTAIN';
  why = 'The provider returned an id (' + providerId + ') on the error path, so the message may have been accepted.';
} else if (PROVES_UNKNOWN.test(message) || code >= 500 || code === 0) {
  outcome = 'UNCERTAIN';
  why = 'The error is a transport or server fault, which can happen after the message is accepted.';
} else if (PROVES_NOT_SENT.test(message) || [400, 401, 403, 404, 422, 429].indexOf(code) !== -1) {
  outcome = 'FAILED_NOT_SENT';
  why = 'The request was refused before the message could be queued.';
} else {
  outcome = 'UNCERTAIN';
  why = 'The error was not recognised, so it cannot be treated as proof that nothing was sent.';
}

const detail = 'HTTP ' + (code || 'none') + '. ' + (message || 'no error message');

return [{ json: {
  send_outcome: outcome,
  outcome_direction: outcome === 'FAILED_NOT_SENT' ? 'OUTBOUND_FAILED' : 'OUTBOUND_UNCERTAIN',
  outcome_classification: outcome === 'FAILED_NOT_SENT' ? 'OUTBOUND_FAILED' : 'OUTBOUND_UNCERTAIN',
  outcome_summary: outcome === 'FAILED_NOT_SENT'
    ? 'The send was refused before delivery. Nothing was sent. ' + why + ' ' + detail
      + ' This attempt does not block a retry.'
    : 'The send did not report a usable outcome. I do not know whether it was delivered. ' + why
      + ' ' + detail
      + ' Check the sent mail before approving anything again. This attempt blocks a retry until a human resolves it.',
  outcome_error_code: code,
  outcome_error_message: message,
  outcome_provider_id: providerId,
} }];

// ============================================================================
// INTEGRITY GUARD — fail closed before drafting, approval, state writes or send.
//
// WHY THIS EXISTS. action_id is not unique in the Actions register. 7 ids hold 2
// rows each, and idempotency_key is duplicated on 6 of them, so neither column
// identifies a row. Two independent selection faults follow from that:
//
//   READ vs READ.  Reselect Action If Drafted takes ready[0] (FIRST match) and is
//   authoritative for what gets drafted. Approval Gate takes ahits[length-1]
//   (LAST match) and validates recipient and channel. On ACT-20260101-001-005
//   those are different rows: OBTAIN_REPAIR_QUOTE / "preferred repairer" / MANUAL
//   versus FOLLOW_UP / "Riverside car park/centre management" / GMAIL.
//
//   READ vs WRITE.  Google Sheets appendOrUpdate updates the FIRST match, while
//   almost every reader in this workflow takes the LAST. So a send can be recorded
//   against one row while a different row stays open.
//
// HOW THE GUARD CLOSES BOTH. It does not choose between rows and it does not rank
// them. It refuses to let the branch continue whenever more than one row could be
// selected. When it passes, every in-scope action_id resolves to exactly ONE row,
// so first === last === newest === oldest, and both mismatches become unreachable
// rather than merely unlikely. Containment by elimination, not by arbitration.
//
// It never uses updated_at, created_at, row order or row number to prefer a row.
// Those appear only in the conflict report, so a human can tell the rows apart.
//
// Nothing here writes, approves, drafts, sends or mutates. Read-only.
// ============================================================================

const cfg = $('Config').first().json;
const passthrough = $input.first().json;
const actions = $('Load Actions').all().map(i => i.json).filter(r => r && r.action_id);
const approvals = (() => { try { return $('Load Approvals').all().map(i => i.json).filter(r => r && r.approval_id); }
                           catch (e) { return []; } })();

const S = v => String(v === null || v === undefined ? '' : v).trim();
const U = v => S(v).toUpperCase();

// Content fingerprint. Excludes mutable state (status, updated_at, draft_id,
// approval_id, blocked_reason) so a row stays identifiable across a legal update.
const FP_FIELDS = ['action_id', 'matter_id', 'action_type', 'priority', 'depends_on_json',
  'recipient', 'channel', 'requires_approval', 'idempotency_key', 'created_at'];
function fnv(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return ('00000000' + h.toString(16)).slice(-8);
}
function fingerprint(row) {
  const basis = FP_FIELDS.map(f => S(row[f])).join('|');
  return 'FP-' + fnv(basis) + fnv(basis.split('').reverse().join('') + '|salt2');
}
function rowRef(row, idx) {
  return { snapshot_index: idx, fingerprint: fingerprint(row),
    action_id: S(row.action_id), idempotency_key: S(row.idempotency_key),
    action_type: U(row.action_type), created_at: S(row.created_at) };
}

function halt(code, reason, detail) {
  return [{ json: {
    ...passthrough,
    integrity_ok: false,
    gate: 'DATA_INTEGRITY_CONFLICT',
    integrity_code: code,
    integrity_reason: reason,
    integrity_detail: detail || [],
    // Deliberately absent: any selected row, any winner, any ranking.
  } }];
}

// ---- 1. Establish scope -----------------------------------------------------
// APPROVAL route: the one action the approval names.
// DRAFT route: every action on the matter, because Reselect chooses among them,
// so ambiguity anywhere in that set can change which action is drafted.
const routeGroup = U(cfg.route_group);
let scopeIds = [];
let scopeLabel = '';

if (routeGroup === 'APPROVAL') {
  const aprId = S(cfg.approval_id);
  const hits = approvals.filter(a => S(a.approval_id) === aprId);
  if (!aprId) return halt('NO_APPROVAL_ID', 'The approval route ran without an approval_id.');
  if (!hits.length) return halt('APPROVAL_NOT_FOUND', 'Approval ' + aprId + ' is not on the register.');
  if (hits.length > 1) {
    return halt('DUPLICATE_APPROVAL_ROW',
      'Approval ' + aprId + ' appears on ' + hits.length + ' rows. I will not choose between them.',
      hits.map(h => ({ approval_id: h.approval_id, action_id: h.action_id, draft_id: h.draft_id })));
  }
  scopeIds = [S(hits[0].action_id)];
  scopeLabel = 'approval ' + aprId;
} else {
  const matterId = S(cfg.matter_id);
  if (!matterId) return halt('NO_MATTER_ID', 'No matter_id in scope.');
  const mine = actions.filter(a => S(a.matter_id) === matterId);
  if (!mine.length) return halt('NO_ACTIONS_FOR_MATTER', 'Matter ' + matterId + ' has no action rows.');
  scopeIds = Array.from(new Set(mine.map(a => S(a.action_id))));
  scopeLabel = 'matter ' + matterId;
}

// ---- 2-5. Ambiguity checks. Any one of them stops the branch. ---------------
const conflicts = [];
const selected = {};

// Blank identifiers are themselves ambiguity: they cannot address a row.
actions.filter(a => S(a.matter_id) === S(cfg.matter_id) || scopeIds.indexOf(S(a.action_id)) !== -1)
  .forEach((a, i) => {
    if (!S(a.action_id)) conflicts.push({ code: 'BLANK_ACTION_ID', snapshot_index: i });
    if (!S(a.idempotency_key)) conflicts.push({ code: 'BLANK_IDEMPOTENCY_KEY', action_id: S(a.action_id) });
  });

// 3. Duplicate idempotency_key anywhere in scope, even across different action ids.
const keyIndex = {};
actions.forEach((a, i) => {
  if (scopeIds.indexOf(S(a.action_id)) === -1) return;
  const k = S(a.idempotency_key);
  if (!k) return;
  (keyIndex[k] = keyIndex[k] || []).push(rowRef(a, i));
});
Object.keys(keyIndex).forEach(k => {
  if (keyIndex[k].length > 1) {
    conflicts.push({ code: 'DUPLICATE_IDEMPOTENCY_KEY', idempotency_key: k, rows: keyIndex[k] });
  }
});

// 2 + 4 + 5. Duplicate action_id, and field mismatch between rows sharing one id.
const COMPARE = ['action_type', 'recipient', 'channel', 'requires_approval',
  'depends_on_json', 'idempotency_key', 'matter_id'];

scopeIds.forEach(id => {
  const rows = [];
  actions.forEach((a, i) => { if (S(a.action_id) === id) rows.push({ row: a, ref: rowRef(a, i) }); });

  if (rows.length === 0) {
    conflicts.push({ code: 'ACTION_NOT_FOUND', action_id: id });
    return;
  }
  if (rows.length > 1) {
    const differing = COMPARE.filter(f =>
      Array.from(new Set(rows.map(r => f === 'requires_approval' || f === 'action_type' || f === 'channel'
        ? U(r.row[f]) : S(r.row[f])))).length > 1);
    conflicts.push({
      code: differing.length ? 'DUPLICATE_ACTION_ID_FIELD_MISMATCH' : 'DUPLICATE_ACTION_ID',
      action_id: id,
      row_count: rows.length,
      differing_fields: differing,
      // Candidates listed so a human can tell them apart. Order is register order.
      // It carries no meaning and confers no preference.
      candidates: rows.map(r => r.ref),
    });
    return;
  }
  selected[id] = rows[0].ref;   // exactly one row: first === last, unambiguous
});

if (conflicts.length) {
  const worst = conflicts[0];
  return halt(worst.code,
    'More than one Action row could be selected for ' + scopeLabel
    + '. I will not choose between them, and I will not draft, approve, write state or send'
    + ' until a human decides which row is the action. ' + conflicts.length + ' conflict(s) found.',
    conflicts);
}

// ---- Unambiguous. Carry the selection forward. ------------------------------
const scopeFingerprint = 'SCOPE-' + fnv(scopeIds.slice().sort()
  .map(id => id + ':' + selected[id].fingerprint).join('|'));

return [{ json: {
  ...passthrough,
  integrity_ok: true,
  integrity_code: 'OK',
  integrity_scope: scopeLabel,
  integrity_scope_ids: scopeIds,
  integrity_scope_fingerprint: scopeFingerprint,
  selected_rows: selected,
  // Convenience for the approval route, where scope is a single action.
  selected_action_id: scopeIds.length === 1 ? scopeIds[0] : '',
  selected_row_fingerprint: scopeIds.length === 1 ? selected[scopeIds[0]].fingerprint : '',
  selected_row_reference: scopeIds.length === 1 ? selected[scopeIds[0]].snapshot_index : -1,
} }];

// ============================================================================
// VERIFY SELECTED ROW — second fail-closed gate, between Approval Gate and
// Gate Result, so it sits before Mark Approval Approved, Mark Action Sent,
// Hold Action, Await User Edit, Log Dry Run and every Gmail node.
//
// Integrity Guard proved the action was unambiguous BEFORE Approval Gate ran.
// Approval Gate then re-queries by action_id and takes ahits[length-1]. This node
// re-derives the row from the same Load Actions snapshot and requires:
//
//   1. exactly one row still matches the action_id Approval Gate emitted, and
//   2. its fingerprint equals the one Integrity Guard carried, and
//   3. the recipient and channel Approval Gate is about to act on match that row.
//
// If any of those cannot be established, the branch stops. It never repairs, never
// substitutes a row, and never prefers one by recency or position.
//
// Note on scope: while the guard passes, first === last, so Approval Gate's
// last-match query and the guard's single row are provably the same row. This node
// exists so that remains checked rather than assumed — if the register changes
// between the two reads, or a future edit reintroduces ambiguity, it fails closed.
// ============================================================================

const gate = $input.first().json;
const guard = $('Integrity Guard').first().json;
const actions = $('Load Actions').all().map(i => i.json).filter(r => r && r.action_id);

const S = v => String(v === null || v === undefined ? '' : v).trim();
const U = v => S(v).toUpperCase();

const FP_FIELDS = ['action_id', 'matter_id', 'action_type', 'priority', 'depends_on_json',
  'recipient', 'channel', 'requires_approval', 'idempotency_key', 'created_at'];
function fnv(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return ('00000000' + h.toString(16)).slice(-8);
}
function fingerprint(row) {
  const basis = FP_FIELDS.map(f => S(row[f])).join('|');
  return 'FP-' + fnv(basis) + fnv(basis.split('').reverse().join('') + '|salt2');
}
function halt(code, reason, detail) {
  return [{ json: { ...gate, gate: 'DATA_INTEGRITY_CONFLICT',
    integrity_ok: false, integrity_code: code, integrity_reason: reason,
    integrity_detail: detail || [] } }];
}

if (guard.integrity_ok !== true) {
  return halt('GUARD_DID_NOT_PASS', 'Integrity Guard did not pass. Refusing to continue.');
}

// ---------------------------------------------------------------------------
// AN APPROVAL GATE REFUSAL IS ALREADY TERMINAL. DO NOT OVERWRITE ITS REASON.
//
// Approval Gate builds `common` — which is where recipient and channel come from —
// only after its identity and staleness checks have passed. Eight returns fire
// before that point and therefore carry no recipient and no channel:
//   INVALID  decision not from the owner chat
//   INVALID  approval not on the register
//   DUPLICATE approval is not PENDING (already decided) - replay protection
//   INVALID  draft missing
//   STALE    content hash does not match the approved hash - the draft was edited
//   STALE    a newer draft version supersedes this approval
//   INVALID  action missing
//   INVALID  matter owner mismatch
//
// The recipient check below compares S(gate.recipient) against the row. For those
// eight, gate.recipient is '' and never equals the row, so every one of them was
// being converted into RECIPIENT_MISMATCH. Execution 399 on 2026-08-24 proved it:
// a deliberate content-hash mismatch was reported to the owner as a recipient
// conflict, with the remedy 'correct the register rows' — wrong cause, wrong
// remedy. Gate Result never ran, so Log Gate Refusal wrote no Events row and
// Telegram - Gate Refused never fired.
//
// A refusal writes no approval state, changes no action, and sends nothing, so
// there is no row for this node to protect. It is passed through with its own gate
// and gate_reason intact, to Gate Result and on to the refusal audit and the owner
// notice. Fail-closed is unchanged: a refusal still refuses, and it now refuses for
// the reason it actually had.
//
// Only the four gate values that go on to write state or send are verified:
// SEND and DRY_RUN reach the writers and the Gmail nodes; REJECTED and EDIT write
// approval and action state. All four are built from `common`, so they carry the
// recipient and channel this node checks. Their behaviour is unchanged.
//
// integrity_ok must be set explicitly: Selected Row Verified? tests it with strict
// boolean validation, so an absent value is a type error rather than a false.
// ---------------------------------------------------------------------------
const VERIFIED_GATES = ['SEND', 'DRY_RUN', 'REJECTED', 'EDIT'];
const gateValue = U(gate.gate);

if (VERIFIED_GATES.indexOf(gateValue) === -1) {
  return [{ json: { ...gate,
    integrity_ok: true,
    verification_skipped: true,
    verification_skipped_reason: 'Approval Gate already refused with '
      + (gateValue || 'NO_GATE_VALUE') + '. There is no row to verify, and its '
      + 'reason is preserved.' } }];
}

const actionId = S(gate.action_id);
if (!actionId) return halt('NO_ACTION_ID', 'Approval Gate emitted no action_id.');

const rows = actions.filter(a => S(a.action_id) === actionId);
if (rows.length === 0) return halt('ACTION_DISAPPEARED', 'Action ' + actionId + ' is no longer on the register.');
if (rows.length > 1) {
  return halt('AMBIGUOUS_AT_VERIFY',
    'Action ' + actionId + ' resolves to ' + rows.length + ' rows at verification. Refusing to write or send.',
    rows.map(r => ({ action_type: U(r.action_type), recipient: S(r.recipient), channel: U(r.channel),
      idempotency_key: S(r.idempotency_key), created_at: S(r.created_at) })));
}

const row = rows[0];
const expected = (guard.selected_rows || {})[actionId];
if (!expected || !expected.fingerprint) {
  return halt('NO_CARRIED_FINGERPRINT',
    'Integrity Guard carried no fingerprint for ' + actionId + '. Cannot verify the row.');
}
const actual = fingerprint(row);
if (actual !== expected.fingerprint) {
  return halt('FINGERPRINT_CHANGED',
    'The Action row for ' + actionId + ' changed between the guard and the writer.',
    [{ expected: expected.fingerprint, actual: actual }]);
}

// The two fields that decide where an external message would go.
if (S(gate.recipient) !== S(row.recipient)) {
  return halt('RECIPIENT_MISMATCH',
    'Approval Gate resolved a different recipient than the verified row.',
    [{ gate: S(gate.recipient), row: S(row.recipient) }]);
}
if (U(gate.channel) !== U(row.channel) && U(gate.channel) !== 'NONE') {
  return halt('CHANNEL_MISMATCH',
    'Approval Gate resolved a different channel than the verified row.',
    [{ gate: U(gate.channel), row: U(row.channel) }]);
}

return [{ json: { ...gate,
  integrity_ok: true,
  integrity_verified_fingerprint: actual,
  integrity_verified_action_id: actionId } }];

// ============================================================================
// RESOLVE CONFLICT NOTICE v2 — draft only. Never published.
//
// STATE OWNERSHIP. This node owns the DETECTION half of the lifecycle and nothing
// else. It may compute notice_action FIRST, REPEAT_PENDING, REPEAT_RETRY,
// REPEAT_SENT or REPEAT_EXHAUSTED, and it may set notification_status to PENDING,
// FAILED, SENT or EXHAUSTED as a RESTATEMENT of what the register already holds.
//
// It must NEVER originate notified_at. Every notified_at value it emits is copied
// verbatim from the stored row, and is '' on a first sighting. Only the future
// notification sender may set SENT, FAILED, notified_at and last_notification_error,
// because only the sender knows whether a message actually left. If this node could
// write notified_at, the register could claim a delivery that never happened.
// ============================================================================
//
// WHY v1 IS WRONG. v1 computes notify purely from FIRST versus REPEAT. So the
// moment a notice row exists, every later sighting returns notify:false —
// including the case where the row was stored but the notification never went
// out. A conflict that was recorded and never reported would be silently dropped
// forever, and the register would look healthy while the owner heard nothing.
// That is the exact failure this lifecycle exists to prevent.
//
// notified_at alone cannot carry the state. Empty means all of: never attempted,
// attempted and failed, and attempted with an unknown outcome. Those need
// different behaviour, so the status is explicit.
//
// FAIL-SAFE DIRECTION. Where the stored state is unreadable or absent, this
// treats the notice as PENDING and notifies. Notifying twice is an annoyance.
// Never notifying is a conflict nobody hears about.
//
// This node still writes nothing, notifies nothing, and touches no other register.
// ============================================================================

const cfg = $('Config').first().json;
const guard = $('Integrity Guard').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.conflict_key);

// Retry ceiling lives in Config, not here, so it can be tuned without editing logic.
const MAX_ATTEMPTS = (() => {
  const n = parseInt(String(cfg.max_notification_attempts || '').trim(), 10);
  return Number.isNaN(n) || n < 1 ? 3 : n;   // 3 is the fallback, never zero
})();
const S = v => String(v === null || v === undefined ? '' : v).trim();
const U = v => S(v).toUpperCase();
const nowIso = new Date().toISOString();

function fnv(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return ('00000000' + h.toString(16)).slice(-8);
}
function hash64(s) { return fnv(s) + fnv(s.split('').reverse().join('') + '|salt2'); }

function stop(code, reason, extra) {
  return [{ json: { ...guard, notice_action: 'FAIL_CLOSED', notice_code: code,
    notice_reason: reason, notice_written: false, notify: false,
    needs_human_review: true, ...(extra || {}) } }];
}

if (guard.integrity_ok === true) {
  return stop('NOT_A_CONFLICT', 'Integrity Guard passed. There is nothing to record.');
}

const detail = Array.isArray(guard.integrity_detail) ? guard.integrity_detail : [];
const actionIds = {}, fingerprints = {}, types = {};
detail.forEach(c => {
  if (!c || typeof c !== 'object') return;
  if (S(c.code)) types[S(c.code)] = true;
  if (S(c.action_id)) actionIds[S(c.action_id)] = true;
  [].concat(Array.isArray(c.candidates) ? c.candidates : [], Array.isArray(c.rows) ? c.rows : [])
    .forEach(r => {
      if (!r) return;
      if (S(r.action_id)) actionIds[S(r.action_id)] = true;
      if (S(r.fingerprint)) fingerprints[S(r.fingerprint)] = true;
    });
});
if (S(guard.integrity_code)) types[S(guard.integrity_code)] = true;

const sortedActions = Object.keys(actionIds).sort();
const sortedPrints = Object.keys(fingerprints).sort();
const sortedTypes = Object.keys(types).sort();
const matterId = S(cfg.matter_id);

if (!matterId) return stop('NO_MATTER_ID', 'No matter_id in scope. Cannot key a conflict notice.');
if (!sortedActions.length && !sortedPrints.length) {
  return stop('NO_CONFLICT_MATERIAL', 'The guard reported a conflict with no action ids or fingerprints.');
}

const basis = [matterId, sortedActions.join(','), sortedPrints.join(','), sortedTypes.join(',')].join('|');
const conflictKey = 'CFL-' + hash64(basis);

const hits = rows.filter(r => S(r.conflict_key) === conflictKey);

if (hits.length > 1) {
  return stop('DUPLICATE_CONFLICT_KEY',
    'The conflict register already holds ' + hits.length + ' rows for ' + conflictKey
    + '. I will not update one of them and leave the others. Nothing was written.',
    { conflict_key: conflictKey, duplicate_row_count: hits.length });
}

const common = {
  conflict_key: conflictKey,
  integrity_code: S(guard.integrity_code),
  matter_id: matterId,
  action_ids_json: JSON.stringify(sortedActions),
  fingerprints_json: JSON.stringify(sortedPrints),
  conflict_types_json: JSON.stringify(sortedTypes),
  source_workflow: '4 - Research Drafting Approval and Dispatch',
  execution_id: S(cfg.execution_id),
};

// ---- FIRST SIGHTING -------------------------------------------------------
if (hits.length === 0) {
  return [{ json: { ...guard, ...common,
    notice_action: 'FIRST',
    occurrence_count: 1,
    first_seen_at: nowIso,
    last_seen_at: nowIso,
    notified_at: '',              // OWNED BY THE SENDER. Never originated here.
    notification_status: 'PENDING',
    notification_attempts: 0,
    last_notification_error: '',
    notify: true,
    notice_written: false,
    needs_human_review: false,
  } }];
}

// ---- A ROW ALREADY EXISTS -------------------------------------------------
const prior = hits[0];
const priorCount = parseInt(S(prior.occurrence_count), 10);
const attempts = (() => { const n = parseInt(S(prior.notification_attempts), 10); return Number.isNaN(n) ? 0 : n; })();
const storedStatus = U(prior.notification_status);
const notifiedAt = S(prior.notified_at);

// Legacy or blank status. Trust notified_at if it is populated, otherwise assume
// PENDING: silence is the worse error.
let status = storedStatus;
if (!status) status = notifiedAt ? 'SENT' : 'PENDING';

const base = { ...guard, ...common,
  occurrence_count: (Number.isNaN(priorCount) ? 1 : priorCount) + 1,
  first_seen_at: S(prior.first_seen_at) || nowIso,
  last_seen_at: nowIso,
  notified_at: notifiedAt,        // echoed from the stored row, never minted here
  notification_attempts: attempts,
  last_notification_error: S(prior.last_notification_error),
  notice_written: false,
};

if (status === 'SENT') {
  // Already reported, and the fingerprint has not changed, so there is nothing new
  // to say. The occurrence count still moves so the register shows the pressure.
  return [{ json: { ...base, notice_action: 'REPEAT_SENT',
    notification_status: 'SENT', notify: false, needs_human_review: false } }];
}

if (status === 'FAILED' && attempts >= MAX_ATTEMPTS) {
  // Stop retrying, but do NOT mark it sent and do not go quiet in the register.
  return [{ json: { ...base, notice_action: 'REPEAT_EXHAUSTED',
    notification_status: 'EXHAUSTED', notify: false, needs_human_review: true,
    notice_reason: 'Notification failed ' + attempts + ' times for ' + conflictKey
      + '. I stopped retrying. The conflict is unresolved and unreported.' } }];
}

if (status === 'EXHAUSTED') {
  return [{ json: { ...base, notice_action: 'REPEAT_EXHAUSTED',
    notification_status: 'EXHAUSTED', notify: false, needs_human_review: true,
    notice_reason: 'Notification for ' + conflictKey + ' was already abandoned after '
      + attempts + ' attempts. It remains unresolved and unreported.' } }];
}

// PENDING, or FAILED with attempts remaining. This is the case v1 lost.
return [{ json: { ...base,
  notice_action: status === 'FAILED' ? 'REPEAT_RETRY' : 'REPEAT_PENDING',
  notification_status: status === 'FAILED' ? 'FAILED' : 'PENDING',
  notify: true,
  needs_human_review: false,
} }];

// ============================================================================
// VERIFY CONFLICT NOTICE — runs after the upsert, on a fresh read of the register.
//
// Google Sheets has no unique constraint and appendOrUpdate is not atomic against
// a concurrent writer. This node cannot prevent a race; it detects one. If the
// register now holds more than one row for our conflict_key, the write is reported
// as UNVERIFIED and the notice is marked not-notifiable, so a later notification
// step can never fire on a register we do not trust.
//
// It writes nothing and repairs nothing. Removing a duplicate row is a human
// decision, exactly as it is for the Actions register.
// ============================================================================

const notice = $('Resolve Conflict Notice').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.conflict_key);

const S = v => String(v === null || v === undefined ? '' : v).trim();
const key = S(notice.conflict_key);

function out(o) { return [{ json: { ...notice, ...o } }]; }

if (!key) {
  return out({ notice_written: false, notice_verified: false,
    notice_code: 'NO_KEY_TO_VERIFY', notify: false });
}

const hits = rows.filter(r => S(r.conflict_key) === key);

if (hits.length === 0) {
  return out({ notice_written: false, notice_verified: false,
    notice_code: 'WRITE_NOT_VISIBLE',
    notice_reason: 'The upsert reported success but no row for ' + key + ' is readable.',
    notify: false });
}

if (hits.length > 1) {
  return out({ notice_written: true, notice_verified: false,
    notice_code: 'DUPLICATE_AFTER_WRITE',
    notice_reason: 'The register holds ' + hits.length + ' rows for ' + key
      + ' after the write. A concurrent writer is the likely cause. Suppression cannot be'
      + ' trusted, so this notice is not notifiable and needs manual review.',
    duplicate_row_count: hits.length,
    notify: false });
}

const stored = hits[0];
const countOk = S(stored.occurrence_count) === String(notice.occurrence_count);
const keyOk = S(stored.matter_id) === S(notice.matter_id);

if (!countOk || !keyOk) {
  return out({ notice_written: true, notice_verified: false,
    notice_code: 'STORED_ROW_MISMATCH',
    notice_reason: 'The stored row does not match what was written.',
    notify: false });
}

return out({ notice_written: true, notice_verified: true, notice_code: 'VERIFIED' });

// ============================================================================
// EVALUATE SEND ELIGIBILITY — decides whether a conflict notice may be sent, and
// builds the payload. It sends nothing itself.
//
// FOUR CONDITIONS, ALL REQUIRED:
//   1. notice_action is FIRST, REPEAT_PENDING or REPEAT_RETRY
//   2. notice_verified is true            (the register write was confirmed)
//   3. notification_status is PENDING or FAILED
//   4. notification_attempts < max_notification_attempts
//
// DESTINATION IS FIXED. The owner chat id comes from Config and nowhere else.
// An Action row can carry a recipient chosen by a planner from a conflicted
// register; routing a message there would turn a data-integrity fault into an
// external disclosure. The destination is therefore never read from an action,
// an approval, a draft or the notice itself.
//
// PAYLOAD IS IDENTIFIERS ONLY. conflict_key, matter_id, action ids, conflict
// types, fingerprints, counts. No recipient, no channel, no description, no
// draft content. The owner is told WHICH conflict, not what the work said.
// ============================================================================

const cfg = $('Config').first().json;
const n = $input.first().json;

const S = v => String(v === null || v === undefined ? '' : v).trim();
const U = v => S(v).toUpperCase();

const MAX_ATTEMPTS = (() => {
  const v = parseInt(S(cfg.max_notification_attempts), 10);
  return Number.isNaN(v) || v < 1 ? 3 : v;
})();

// The one permitted destination. Hardcoded in Config, never derived from data.
const OWNER_CHAT_ID = S(cfg.owner_chat_id);

const ALLOWED_ACTIONS = ['FIRST', 'REPEAT_PENDING', 'REPEAT_RETRY'];
const ALLOWED_STATUS = ['PENDING', 'FAILED'];

const attempts = (() => { const v = parseInt(S(n.notification_attempts), 10); return Number.isNaN(v) ? 0 : v; })();

const checks = {
  action_allowed: ALLOWED_ACTIONS.indexOf(U(n.notice_action)) !== -1,
  register_verified: n.notice_verified === true,
  status_allowed: ALLOWED_STATUS.indexOf(U(n.notification_status)) !== -1,
  attempts_remaining: attempts < MAX_ATTEMPTS,
  destination_fixed: !!OWNER_CHAT_ID,
};
const blockedBy = Object.keys(checks).filter(k => !checks[k]);
const eligible = blockedBy.length === 0;

if (!eligible) {
  return [{ json: { ...n, send_eligible: false, send_blocked_by: blockedBy,
    send_outcome: 'NOT_ATTEMPTED', notification_attempts: attempts } }];
}

let ids = [], types = [], prints = [];
try { ids = JSON.parse(n.action_ids_json || '[]'); } catch (e) {}
try { types = JSON.parse(n.conflict_types_json || '[]'); } catch (e) {}
try { prints = JSON.parse(n.fingerprints_json || '[]'); } catch (e) {}

const body = [
  'Data integrity conflict. I stopped before drafting, approving or sending.',
  '',
  'Conflict: ' + S(n.conflict_key),
  'Matter: ' + S(n.matter_id),
  'Actions: ' + (ids.length ? ids.join(', ') : 'none recorded'),
  'Types: ' + (types.length ? types.join(', ') : 'none recorded'),
  'Row fingerprints: ' + (prints.length ? prints.join(', ') : 'none recorded'),
  'Seen ' + S(n.occurrence_count) + ' time(s) since ' + S(n.first_seen_at).slice(0, 10) + '.',
  '',
  'More than one Action row could be selected for this work, so I will not choose'
  + ' between them. Nothing was drafted, approved, written or sent.',
  'A human must decide which row is the action. The rows are on the Actions tab.',
].join('\n');

return [{ json: { ...n,
  send_eligible: true,
  send_blocked_by: [],
  notification_attempts: attempts,
  // Attempt number this send WOULD be. Only the recorder may persist it.
  attempt_number: attempts + 1,
  notify_chat_id: OWNER_CHAT_ID,
  notify_text: body,
  send_outcome: 'NOT_ATTEMPTED',
} }];

// PLACEHOLDER. No sender is built. This node performs no I/O of any kind:
// no HTTP, no Telegram, no Gmail. It exists so the branch is complete and
// testable, and so that publishing WF4 cannot deliver anything by accident.
//
// NOT_IMPLEMENTED is handled explicitly downstream: no status change, no
// attempt consumed, notified_at untouched. The notice stays PENDING and keeps
// appearing in the daily digest, which is the honest state until a real sender
// is approved and built.
const n = $input.first().json;
return [{ json: { ...n, send_outcome: 'NOT_IMPLEMENTED',
  send_error: '', sender_note: 'No notification sender is built in this draft.' } }];

// ============================================================================
// CLASSIFY NOTIFICATION OUTCOME — turns a send result into a state transition.
//
// It may set SENT and notified_at, FAILED and last_notification_error, or
// EXHAUSTED. It is the ONLY node permitted to do so, because it is the only one
// downstream of the sender.
//
// IT NEVER CLAIMS A SEND IT CANNOT SEE. SUCCESS is the only outcome that yields
// SENT and a notified_at. Every other outcome, including an unrecognised one,
// leaves the notice notifiable or escalates it. Silence is the worse error.
//
// NOT_IMPLEMENTED is a first-class outcome. The sender in this draft is a
// placeholder that performs no I/O, so the branch must not burn an attempt or
// mark anything sent. The notice stays PENDING and keeps appearing in the daily
// digest, which is the honest state until a real sender is approved and built.
// ============================================================================

const cfg = $('Config').first().json;
const n = $input.first().json;

const S = v => String(v === null || v === undefined ? '' : v).trim();
const U = v => S(v).toUpperCase();
const nowIso = new Date().toISOString();

const MAX_ATTEMPTS = (() => {
  const v = parseInt(S(cfg.max_notification_attempts), 10);
  return Number.isNaN(v) || v < 1 ? 3 : v;
})();

const priorAttempts = (() => { const v = parseInt(S(n.notification_attempts), 10); return Number.isNaN(v) ? 0 : v; })();
const outcome = U(n.send_outcome) || 'NOT_ATTEMPTED';

// Diagnostic text is sanitised: identifiers and status only. A provider error can
// echo the payload back, and the payload must never carry matter content anyway,
// but this is belt and braces.
function safeError(raw) {
  let t = S(raw);
  t = t.replace(/[A-Za-z0-9_\-]{32,}/g, '[redacted]');
  t = t.replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[address redacted]');
  return t.slice(0, 200);
}

function out(o) { return [{ json: { ...n, ...o, status_write_needed: o.status_write_needed } }]; }

// Not eligible, or the placeholder ran. Nothing changes in the register.
if (outcome === 'NOT_ATTEMPTED' || outcome === 'NOT_IMPLEMENTED') {
  return out({
    notification_status: U(n.notification_status) || 'PENDING',
    notification_attempts: priorAttempts,
    notified_at: S(n.notified_at),
    last_notification_error: S(n.last_notification_error),
    status_write_needed: false,
    transition: outcome === 'NOT_IMPLEMENTED' ? 'NO_SENDER_BUILT' : 'NOT_ELIGIBLE',
    transition_note: outcome === 'NOT_IMPLEMENTED'
      ? 'No notification sender is built. The notice stays PENDING and remains visible in the daily digest.'
      : 'The notice was not eligible to send. Nothing changed.',
  });
}

if (outcome === 'SUCCESS') {
  return out({
    notification_status: 'SENT',
    notification_attempts: priorAttempts + 1,
    notified_at: nowIso,                     // the ONLY place this is ever minted
    last_notification_error: '',
    status_write_needed: true,
    transition: 'PENDING_TO_SENT',
  });
}

// Any failure, including an outcome this node does not recognise.
const attempts = priorAttempts + 1;
const exhausted = attempts >= MAX_ATTEMPTS;
return out({
  notification_status: exhausted ? 'EXHAUSTED' : 'FAILED',
  notification_attempts: attempts,
  notified_at: S(n.notified_at),             // still empty. Never claim a delivery.
  last_notification_error: safeError(n.send_error || ('Unrecognised send outcome: ' + outcome)),
  status_write_needed: true,
  needs_human_review: exhausted ? true : (n.needs_human_review === true),
  transition: exhausted ? 'FAILED_TO_EXHAUSTED' : 'ATTEMPT_FAILED',
  transition_note: exhausted
    ? 'Notification failed ' + attempts + ' times. I stopped retrying. The conflict is unresolved and unreported.'
    : 'Attempt ' + attempts + ' of ' + MAX_ATTEMPTS + ' failed. It will be retried.',
});

// ============================================================================
// VERIFY NOTIFICATION RECORD — re-reads the register after the status write.
//
// THE CASE THIS EXISTS FOR. A message can leave and the status write can then
// fail. The register would still say PENDING, the next run would retry, and the
// owner would be told twice. That is a real duplicate-delivery path and it is
// NOT closed by anything here. This node detects it and says so plainly.
//
// It cannot be closed by ordering either: writing SENT before sending would let
// a failed send be recorded as delivered, which is worse. Given the choice
// between a possible duplicate and a possible silence, this design takes the
// duplicate. THERE IS NO EXACTLY-ONCE DELIVERY GUARANTEE HERE.
//
// This node writes nothing and repairs nothing.
// ============================================================================

const n = $('Classify Notification Outcome').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.conflict_key);

const S = v => String(v === null || v === undefined ? '' : v).trim();
const U = v => S(v).toUpperCase();
const key = S(n.conflict_key);

function out(o) { return [{ json: { ...n, ...o } }]; }

if (n.status_write_needed !== true) {
  return out({ notification_recorded: false, notification_record_code: 'NO_WRITE_ATTEMPTED' });
}

const hits = rows.filter(r => S(r.conflict_key) === key);

if (hits.length > 1) {
  return out({ notification_recorded: false, notification_record_code: 'DUPLICATE_AFTER_NOTIFICATION',
    needs_human_review: true,
    notification_record_note: 'The register holds ' + hits.length + ' rows for ' + key
      + '. Suppression cannot be trusted and this notice may be sent again.' });
}

if (hits.length === 0) {
  return out({ notification_recorded: false, notification_record_code: 'RECORD_NOT_VISIBLE',
    needs_human_review: true,
    notification_record_note: U(n.notification_status) === 'SENT'
      ? 'A notification was sent but no register row is readable. It will be sent again on the next run.'
      : 'The status write is not readable.' });
}

const stored = hits[0];
const statusOk = U(stored.notification_status) === U(n.notification_status);
const attemptsOk = S(stored.notification_attempts) === String(n.notification_attempts);

if (!statusOk || !attemptsOk) {
  // The decisive case: the message went out, the register does not know it.
  const sentButUnrecorded = U(n.notification_status) === 'SENT' && U(stored.notification_status) !== 'SENT';
  return out({ notification_recorded: false,
    notification_record_code: sentButUnrecorded ? 'SENT_BUT_NOT_RECORDED' : 'RECORD_MISMATCH',
    needs_human_review: true,
    notification_record_note: sentButUnrecorded
      ? 'A notification was delivered but the register still shows '
        + (U(stored.notification_status) || 'no status')
        + '. The next run will treat it as unsent and send it again. This is a known duplicate path.'
      : 'The stored row does not match the transition that was written.' });
}

return out({ notification_recorded: true, notification_record_code: 'RECORDED' });

// Build Integrity Halt Notice
// ===========================================================================
// WHY THIS NODE EXISTS
//
// "Halt - Data Integrity Conflict" was a terminal NoOp. Every containment path
// in this workflow ends there: the Integrity Guard refusal, the Verify Selected
// Row refusal, an unrecognised route_group, and eight error outputs from the
// conflict-notice chain. A run that reached it produced NO owner message and NO
// audit row. From the owner's side that is indistinguishable from the bot being
// broken, and a real integrity conflict could sit unreported indefinitely.
//
// This node does no I/O. It normalises whatever item arrived into one reporting
// shape. The nodes after it write one Events row and send ONE Telegram notice to
// the owner chat from Config.
//
// WHAT IT DELIBERATELY DOES NOT CARRY
// No draft content, no facts, no evidence, no recipient address, no subject, no
// model output. Identifiers, codes and row metadata only. The destination is
// always Config.owner_chat_id and never a value taken from a register row, so
// this cannot become a dispatch path. No approval command is offered.
// ===========================================================================

const cfg = (() => { try { return $('Config').first().json || {}; } catch (e) { return {}; } })();

const S = v => String(v === null || v === undefined ? '' : v).trim();
const esc = s => String(s === null || s === undefined ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Stable 32-bit FNV-1a, used only to make the Events row id deterministic so a
// repeated identical conflict updates one row instead of appending forever.
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ('0000000' + h.toString(16)).slice(-8).toUpperCase();
}

const item = (() => { try { return $input.first().json || {}; } catch (e) { return {}; } })();

// ---- CLASSIFY THE ARRIVING ITEM -------------------------------------------
// Five shapes can reach this node. Anything unrecognised is still reported,
// never swallowed.
let stage, code, reason;
const detail = Array.isArray(item.integrity_detail) ? item.integrity_detail : [];

const GUARD_CODES = ['NO_APPROVAL_ID', 'APPROVAL_NOT_FOUND', 'DUPLICATE_APPROVAL_ROW',
  'NO_MATTER_ID', 'NO_ACTIONS_FOR_MATTER', 'BLANK_ACTION_ID', 'BLANK_IDEMPOTENCY_KEY',
  'DUPLICATE_IDEMPOTENCY_KEY', 'ACTION_NOT_FOUND', 'DUPLICATE_ACTION_ID',
  'DUPLICATE_ACTION_ID_FIELD_MISMATCH'];
const VERIFY_CODES = ['GUARD_DID_NOT_PASS', 'NO_ACTION_ID', 'ACTION_DISAPPEARED',
  'AMBIGUOUS_AT_VERIFY', 'NO_CARRIED_FINGERPRINT', 'FINGERPRINT_CHANGED',
  'RECIPIENT_MISMATCH', 'CHANNEL_MISMATCH'];

const rawErr = item.error !== undefined ? item.error : undefined;

if (S(item.integrity_code)) {
  code = S(item.integrity_code);
  reason = S(item.integrity_reason);
  if (code === 'UNKNOWN_ROUTE_GROUP') stage = 'ROUTING';
  else if (VERIFY_CODES.indexOf(code) !== -1) stage = 'APPROVAL_ROW_VERIFICATION';
  else if (GUARD_CODES.indexOf(code) !== -1) stage = 'PRE_DRAFT_INTEGRITY_GUARD';
  else stage = 'INTEGRITY_CHECK';
} else if (rawErr !== undefined) {
  stage = 'CONTAINMENT_PATH_NODE_ERROR';
  code = 'NODE_ERROR_ON_CONTAINMENT_PATH';
  const m = (rawErr && typeof rawErr === 'object')
    ? (rawErr.message || rawErr.description || JSON.stringify(rawErr))
    : String(rawErr);
  reason = S(m).slice(0, 300);
} else if (S(item.conflict_key) || S(item.notification_status) || S(item.notice_verified)) {
  stage = 'CONFLICT_NOTICE_CHAIN';
  code = 'CONFLICT_NOTICE_RECORDED';
  reason = 'A data integrity conflict was recorded in the ConflictNotices register. '
    + 'No notification sender is built, so this message is the notification.';
} else {
  stage = 'UNCLASSIFIED';
  code = 'HALT_REACHED_WITHOUT_CODE';
  reason = 'The containment path was reached but the item carried no integrity code. '
    + 'Read the execution record.';
}

// ---- IDENTIFIERS -----------------------------------------------------------
// Config is the reliable source; the item is only a fallback. The guard-side
// halt item is a Load Evidence passthrough and may carry neither.
const matterId   = S(cfg.matter_id)   || S(item.matter_id)   || '';
const actionId   = S(item.action_id)  || '';
const approvalId = S(cfg.approval_id) || S(item.approval_id) || '';
const routeGroup = S(cfg.route_group) || S(item.route_group) || '';
const conflictKey = S(item.conflict_key) || '';
const dryRun = S(cfg.dry_run).toLowerCase() === 'true';

// ---- CONFLICTING RECORDS ---------------------------------------------------
// Identifiers and row metadata only.
function detailLine(d) {
  if (!d || typeof d !== 'object') return '  ' + S(d).slice(0, 120);
  const bits = [];
  if (S(d.code)) bits.push(S(d.code));
  if (S(d.action_id)) bits.push('action ' + S(d.action_id));
  if (S(d.idempotency_key)) bits.push('key ' + S(d.idempotency_key));
  if (d.row_count !== undefined) bits.push(S(d.row_count) + ' rows');
  if (Array.isArray(d.differing_fields) && d.differing_fields.length) {
    bits.push('fields differ: ' + d.differing_fields.join(', '));
  }
  if (Array.isArray(d.candidates) && d.candidates.length) {
    bits.push('candidates: ' + d.candidates
      .map(c => S(c.action_type) || '?')
      .join(' vs '));
  }
  if (d.expected !== undefined || d.actual !== undefined) {
    bits.push('expected ' + S(d.expected).slice(0, 40) + ', actual ' + S(d.actual).slice(0, 40));
  }
  if (!bits.length) bits.push(JSON.stringify(d).slice(0, 160));
  return '  ' + bits.join('  ');
}
const MAX_DETAIL = 5;
const shown = detail.slice(0, MAX_DETAIL).map(detailLine);
const hidden = Math.max(0, detail.length - shown.length);

// ---- MESSAGE ---------------------------------------------------------------
const lines = [];
lines.push('INTEGRITY HALT');
lines.push('I stopped this request. Nothing was drafted, approved, or sent.');
lines.push('');
lines.push('Matter:   ' + (matterId   || 'not recorded on this item'));
lines.push('Action:   ' + (actionId   || 'not recorded on this item'));
lines.push('Approval: ' + (approvalId || 'not applicable'));
lines.push('Route:    ' + (routeGroup || 'not recorded'));
lines.push('Stage:    ' + stage);
lines.push('Code:     ' + code);
if (conflictKey) lines.push('Conflict key: ' + conflictKey);
lines.push('');
lines.push('Reason:');
lines.push('  ' + (reason || 'No reason string was recorded.'));
if (shown.length) {
  lines.push('');
  lines.push('Conflicting records (' + detail.length + '):');
  shown.forEach(l => lines.push(l));
  if (hidden) lines.push('  ... and ' + hidden + ' more. The full list is in the execution record.');
}
lines.push('');
// The explanation must match the halt that actually happened. An earlier version
// printed the duplicate-row wording unconditionally, so an unknown route told the
// owner that rows conflicted and asked them to correct rows it had never named.
lines.push('What this means:');
if (stage === 'ROUTING') {
  lines.push('  I received an instruction this workflow does not implement.');
  lines.push('  I will not substitute the nearest route that I do implement.');
} else if (stage === 'CONTAINMENT_PATH_NODE_ERROR') {
  lines.push('  A step on the containment path itself failed.');
  lines.push('  The stop still held. Nothing was drafted, approved, or sent.');
} else if (detail.length) {
  lines.push('  More than one register row could have been used, or a check did not pass.');
  lines.push('  I will not choose between them and I will not guess.');
} else {
  lines.push('  A safety check did not pass. I stopped instead of continuing.');
  lines.push('  I will not guess my way past it.');
}
lines.push('');
lines.push(dryRun
  ? 'Dry run is ON. No external message could have been sent in any case.'
  : 'DRY RUN IS OFF. Nothing was sent, because this run stopped before the send gate.');
lines.push(detail.length
  ? 'Correct the register rows named above, then send the request again.'
  : 'Check the request and the execution record, then send the request again.');
lines.push('I am not asking you to approve anything. There is nothing to approve.');

const raw = lines.join('\n');
const reply = esc(raw);

// ---- AUDIT ROW -------------------------------------------------------------
// Deterministic id: an identical conflict updates one row rather than appending
// a new one on every retry. Distinct conflicts get distinct ids.
const idSeed = [code, matterId, actionId, approvalId, conflictKey,
  detail.map(d => (d && d.code) + ':' + (d && d.action_id)).join('|')].join('~');
const eventId = 'EVT-INTEGRITY-' + fnv1a(idSeed);

const auditMessage = [code, stage, reason].filter(Boolean).join(' | ').slice(0, 900);

return [{ json: {
  reply: reply,
  reply_chars: reply.length,
  event_id: eventId,
  event_type: 'DATA_INTEGRITY_HALT',
  severity: 'ERROR',
  halt_stage: stage,
  halt_code: code,
  halt_reason: reason,
  halt_matter_id: matterId,
  halt_action_id: actionId,
  halt_approval_id: approvalId,
  halt_route_group: routeGroup,
  halt_conflict_count: detail.length,
  halt_audit_message: auditMessage,
  dry_run: dryRun,
} }];

// Unknown Route - Fail Closed
// ===========================================================================
// The Mode switch had fallbackOutput wired to Build Draft Context, so a
// route_group the workflow does not implement was silently treated as DRAFT.
// That is fail-open on an unknown route, which safety rule 6 forbids: an
// unrecognised instruction must stop, not pick the nearest branch.
//
// This node performs no I/O. It converts the unknown route into the same halt
// shape the Integrity Guard emits, so it reaches the existing containment
// terminus and the owner notification built on it.
// ===========================================================================

const cfg = (() => { try { return $('Config').first().json || {}; } catch (e) { return {}; } })();
const passthrough = (() => { try { return $input.first().json || {}; } catch (e) { return {}; } })();

const rg = String(cfg.route_group === null || cfg.route_group === undefined ? '' : cfg.route_group).trim();

return [{ json: Object.assign({}, passthrough, {
  integrity_ok: false,
  gate: 'DATA_INTEGRITY_CONFLICT',
  integrity_code: 'UNKNOWN_ROUTE_GROUP',
  integrity_reason: 'route_group ' + (rg ? '"' + rg + '"' : '(empty)')
    + ' is not a route this workflow implements. The routes are DRAFT and APPROVAL. '
    + 'I stopped instead of assuming DRAFT.',
  integrity_detail: [],
}) }];

// ============================================================================
// BUILD NOTIFICATION FAILURE RECORD
//
// Runs ONLY on the error output of `Telegram - Integrity Halt`.
//
// WHAT THIS EXISTS FOR. The integrity-halt notice is the owner's only signal
// that a matter was stopped before drafting, approval or dispatch. That Telegram
// node was continueRegularOutput, so a 400, a timeout or an auth failure was
// swallowed: the run walked on to `Integrity Halt Reported` and finished looking
// clean while the owner had been told nothing at all. This node turns that
// silence into a recorded fact.
//
// IT NEVER TOUCHES THE ORIGINAL HALT. The halt's event_id, its Events row and
// its reason are read and carried, never rewritten. This node mints its OWN
// event_id under a different prefix, so the two rows coexist in the register:
// the halt itself, and the separate fact that the halt could not be delivered.
//
// NO RETRY. NO SECOND SENDER. It performs no I/O of any kind. It does not
// resend, does not queue, does not fall back to another channel and does not
// hand the message to the error workflow. A notification that failed stays
// failed and stays visible. Re-sending from here would be a second external
// dispatch inside a containment guard, which is the thing this whole branch
// exists to prevent.
//
// THE MATTER STAYS BLOCKED. Nothing here changes matter, action, approval or
// draft state. The halt already stopped the work; a delivery failure cannot
// unblock it, and this node has no path to anything that could.
// ============================================================================

const notice = $('Build Integrity Halt Notice').first().json;
const cfg    = $('Config').first().json;
const item   = $input.first().json || {};

const S = v => String(v === null || v === undefined ? '' : v).trim();

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return ('0000000' + h.toString(16)).slice(-8).toUpperCase();
}

// ---- EXTRACT THE ERROR -----------------------------------------------------
// n8n places different shapes on a node error output depending on node type and
// version. Read every known location rather than assuming one, and never let a
// missing shape produce an empty record: an unexplained failure is still a
// failure and must still be written.
const errObj = (item.error && typeof item.error === 'object' && !Array.isArray(item.error))
  ? item.error : {};
const errStr = (typeof item.error === 'string') ? item.error : '';

const rawMessage = S(errObj.message) || errStr || S(item.message)
  || S(errObj.description) || S(item.description)
  || 'The node reported a failure but supplied no error text.';

const httpCode = S(errObj.httpCode) || S(item.httpCode) || S(errObj.status)
  || S(errObj.statusCode) || S(errObj.code) || '';
const errName = S(errObj.name) || S(item.name) || '';

// Sanitised for the register: identifiers and status only. A provider error can
// echo the request back. The halt notice carries no matter content by design,
// but this is belt and braces and matches the sanitiser used on the conflict
// notification path.
function safeError(raw) {
  let t = S(raw);
  t = t.replace(/[A-Za-z0-9_\-]{32,}/g, '[redacted]');
  t = t.replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[address redacted]');
  return t.slice(0, 300);
}
const cleanMessage = safeError(rawMessage);

// ---- CLASSIFY, WITHOUT GUESSING --------------------------------------------
// UNCLASSIFIED is a real and acceptable answer. Forcing every failure into a
// named bucket would make the register confidently wrong.
const probe = (rawMessage + ' ' + errName + ' ' + httpCode).toLowerCase();
let failureKind = 'UNCLASSIFIED';

if (/can't parse entities|cant parse entities|parse entities|unsupported start tag|unclosed/.test(probe)) {
  failureKind = 'MESSAGE_REJECTED';
} else if (httpCode === '429' || /too many requests|rate limit|retry after/.test(probe)) {
  failureKind = 'RATE_LIMITED';
} else if (httpCode === '401' || httpCode === '403'
  || /unauthor|forbidden|bot was blocked|chat not found|invalid token|bot token/.test(probe)) {
  failureKind = 'NOT_AUTHORISED';
} else if (/etimedout|esockettimedout|timeout|timed out|econnreset|econnrefused|enotfound|socket hang up|network|aborted/.test(probe)) {
  failureKind = 'UNREACHABLE';
} else if (/^5\d\d$/.test(httpCode)
  || /internal server error|bad gateway|service unavailable|gateway timeout/.test(probe)) {
  failureKind = 'PROVIDER_ERROR';
} else if (httpCode === '400' || /bad request/.test(probe)) {
  failureKind = 'MESSAGE_REJECTED';
}

const haltEventId = S(notice.event_id);

// Deterministic, and deliberately NOT the halt's id. An identical failure on the
// same halt updates one row instead of appending on every occurrence; a halt and
// its delivery failure can never collide, because the prefixes differ.
const eventId = 'EVT-NOTICEFAIL-' + fnv1a((haltEventId || 'NO_HALT_EVENT') + '~' + failureKind);

const auditMessage = [
  'INTEGRITY NOTICE UNDELIVERED',
  failureKind,
  httpCode ? 'http ' + httpCode : '',
  'halt ' + (haltEventId || 'unknown'),
  cleanMessage,
].filter(Boolean).join(' | ').slice(0, 900);

return [{ json: {
  // ---- the delivery failure, as its own event ----
  event_id: eventId,
  event_type: 'INTEGRITY_NOTICE_UNDELIVERED',
  severity: 'ERROR',
  notice_failure_kind: failureKind,
  notice_failure_http_code: httpCode,
  notice_failure_message: cleanMessage,
  notice_failure_audit_message: auditMessage,

  // ---- explicit, machine-readable outcome carried to the terminus ----
  integrity_notice_delivered: false,
  notification_status: 'FAILED',
  notification_retried: false,
  owner_informed: false,
  needs_human_review: true,
  matter_blocked: true,

  // ---- the original halt, carried verbatim, never rewritten ----
  halt_event_id: haltEventId,
  halt_stage: S(notice.halt_stage),
  halt_code: S(notice.halt_code),
  halt_reason: S(notice.halt_reason),
  halt_matter_id: S(notice.halt_matter_id),
  halt_action_id: S(notice.halt_action_id),
  halt_approval_id: S(notice.halt_approval_id),
  halt_route_group: S(notice.halt_route_group),
  halt_conflict_count: notice.halt_conflict_count,
  halt_audit_message: S(notice.halt_audit_message),
  dry_run: notice.dry_run,
  owner_chat_id: S(cfg.owner_chat_id),
} }];
